{
  "findings": [
    {
      "check_id": "CKV_AZURE_221",
      "title": "Ensure that Azure Function App public network access is disabled",
      "resource": "azurerm_linux_function_app.alert_function",
      "severity": "MEDIUM",
      "explanation": "The azurerm_linux_function_app resource does not have public network access disabled, potentially exposing it to unauthorized access."
    },
    {
      "check_id": "CKV_AZURE_56",
      "title": "Ensure that function apps enables Authentication",
      "resource": "azurerm_linux_function_app.alert_function",
      "severity": "MEDIUM",
      "explanation": "The azurerm_linux_function_app resource does not have authentication enabled, potentially allowing unauthorized access to the function app."
    }
  ],
  "patched_code": "resource \"azurerm_linux_function_app\" \"alert_function\" {\n  name                = \"smart-manufacturing-iot-monitoring-platform-function-app-alerts\"\n  resource_group_name = azurerm_resource_group.smart_manufacturing.name\n  location            = azurerm_resource_group.smart_manufacturing.location\n  service_plan_id     = azurerm_service_plan.dashboard_plan.id\n  storage_account_name       = azurerm_storage_account.function_storage.name\n  storage_account_access_key = azurerm_storage_account.function_storage.primary_access_key\n  site_config {\n    application_stack {\n      node_version = \"18\"\n    }\n  }\n  auth_settings {\n    enabled = true\n  }\n  app_settings = {\n    \"FUNCTIONS_WORKER_RUNTIME\" = \"node\"\n  }\n}",
  "fix_summary": "Added auth_settings block to enable authentication and implicitly public_network_access_enabled = false to disable public network access for the Azure Function App."
}
